  // fetchWithRetry — slow/unstable networks drop requests mid-flight; retry with
  // backoff instead of surfacing a dead page. Timeout prevents indefinite hangs.
  async function fetchWithRetry(url, tries) {
    tries = tries || 3;
    let lastErr;
    for (let i = 0; i < tries; i++) {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 20000); // 20s per attempt
      try {
        const res = await fetch(url, { signal: ctrl.signal });
        clearTimeout(timer);
        if (res.status === 429) {
          // rate-limited — wait out the window briefly and retry once more
          lastErr = new Error("rate limited");
          await new Promise(r => setTimeout(r, 1500 * (i + 1)));
          continue;
        }
        const data = await res.json();
        return data;
      } catch (e) {
        clearTimeout(timer);
        lastErr = e;
        if (i < tries - 1) await new Promise(r => setTimeout(r, 800 * (i + 1)));
      }
    }
    throw lastErr || new Error("fetch failed");
  }

  async function loadPageData(page) {
    if (pageCache.has(page)) return pageCache.get(page);
    if (pageLoading.has(page)) return pageLoading.get(page); // join the in-flight load
    const load = (async () => {
      let url;
      if (searchMode) {
        url = "/api/search?q=" + encodeURIComponent(searchKeyword) + "&page=" + page;
      } else {
        url = "/api/videos?page=" + page + "&category=" + encodeURIComponent(currentCategory);
      }
      const data = await fetchWithRetry(url);
      if (!data.success) throw new Error(data.error || "API error");
      const videos = data.videos || [];
      pageCache.set(page, videos);
      return videos;
    })()
      .finally(() => pageLoading.delete(page));
    pageLoading.set(page, load);
    return load;
  }","allowMultiple":false}]}}


