// verification AND the startup cache purge — all three MUST agree, otherwise
// the purge deletes pages the pipeline considers valid and the cache stays
// empty after every restart, forcing 3-8s cold refetches everywhere).
// A card matches if a variant phrase appears in title, pageUrl slug, or its
// OFFICIAL tag metadata (extractCardTags — xhamster's own keyword fields).
function cardMatchesCategory(reCache, c) {
  const title = (c.title || "").toLowerCase();
  const slug = String(c.pageUrl || "").toLowerCase();
  if (reCache.some((re) => re.test(title) || re.test(slug))) return true;
  if (Array.isArray(c.tags) && c.tags.length && reCache.some((re) => c.tags.some((t) => re.test(String(t))))) return true;
  return false;
}
function buildCategoryReCache(variants) {
  return variants.map((kw) => new RegExp("(^|[^a-z])" + kw.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "($|[^a-z])", "i"));
}
function categoryCardsVerified(catKey, cards) {
  if (!cards || cards.length < 10) return false;   // tiny pages are useless — treat as failed
  const reCache = buildCategoryReCache(getCatVariants(catKey));
  let matched = 0;
  for (const c of cards) if (cardMatchesCategory(reCache, c)) matched++;
