async function fetchWithRetry(url, opts, attempts = 2, backoffMs = 400) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      const r = await fetch(url, opts);
      if (r.ok) return r;
      lastErr = new Error("upstream " + r.status);
      if (r.status >= 400 && r.status < 500 && r.status !== 429) return r; // don't retry hard 4xx (except 429)
    } catch (e) { lastErr = e; }
    if (i < attempts - 1) await sleep(backoffMs);
