// RETRY helper (2026-10-16): transient upstream failures (502/timeouts reached
// the player as-is before and stalled/broke playback mid-segment). GETs are
// safe to retry; hard 4xx (except 429) are not — return them as-is.
async function fetchWithRetry(url, opts, attempts = 3, backoffMs = 350) {
  let lastErr = null;
  for (let i = 0; i < attempts; i++) {
    try {
      const r = await fetch(url, opts);
      if (r.ok) return r;
      if (r.status >= 400 && r.status < 500 && r.status !== 429) return r; // hard 4xx — no retry
      lastErr = new Error("upstream " + r.status);
    } catch (e) { lastErr = e; }
    if (i < attempts - 1) await sleep(backoffMs);
  }
  throw lastErr || new Error("upstream failed");
}

// Thumbnail PRE-WARM + in-flight merge (2026-10-16): /api/videos fires this for
// the 30 cards about to render, so by the time the browser asks for each thumb
// the LRU usually has it — the 500-700ms upstream CDN round-trip disappears
// from the user's view. Concurrent duplicate requests share the SAME promise
// instead of each pulling upstream separately.
const thumbInflight = new Map(); // url -> Promise<{buf, ctype}>
function thumbLoadUpstream(url) {
  let p = thumbInflight.get(url);
  if (p) return p;
  p = (async () => {
    try {
      const upstream = await fetchWithRetry(url, {
        headers: { "User-Agent": UA, Referer: "https://xhamster.com/" },
        redirect: "follow",
      }, 2, 250);
      const ctype = upstream.headers.get("content-type") || "image/webp";
      const buf = Buffer.from(await upstream.arrayBuffer());
      if (thumbLRU.size >= THUMB_LRU_MAX) {
        const oldestKey = thumbLRU.keys().next().value;
        if (oldestKey !== undefined) thumbLRU.delete(oldestKey);
      }
      thumbLRU.set(url, { buf, ctype, ts: Date.now() });
      return { buf, ctype };
    } finally { thumbInflight.delete(url); }
  })();
  thumbInflight.set(url, p);
  return p;
}
function warmThumbs(urls) {
  let queued = 0;
  for (const u of urls || []) {
    if (!u || !THUMB_HOST.test(u)) continue;
    if (thumbLRU.has(u)) continue;
    if (thumbInflight.has(u)) continue;
    if (queued >= 20) break;                      // cap per response — paced, not a stampede
    queued++;
    thumbLoadUpstream(u).catch(() => {});         // fire-and-forget; failures just drop
    awaitDelayThumb();
