}
const _thumbPacer = { next: 0 };
async function awaitDelayThumb() { const wait = _thumbPacer.next - Date.now(); if (wait > 0) { await sleep(wait); _thumbPacer.next += 60; } else { _thumbPacer.next = Date.now() + 60; } }","allowMultiple":false}]}}


