async function fetchWithRetry(url, opts, attempts = 3, backoffMs = 350) {
  let lastErr = null;
  for (let i = 0; i < attempts; i++) {
    try {
      const r = await fetch(url, opts);
      if (r.ok) return r;
      if (r.status >= 400 && r.status < 500 && r.status !== 429) return r; // hard 4xx — no retry
      lastErr = new Error("upstream " + r.status);
    } catch (e) { lastErr = e; }
    if (i < attempts - 1) await sleep(backoffMs);
  }
  throw lastErr || new Error("upstream failed");
}

