  const exp = entry.exp || parseStreamExpiry(entry.m3u8Url) || 0;
  if (exp) return now < exp - STREAM_EXPIRY_MARGIN_MS;
  return now - (entry.ts || 0) < STREAM_CACHE_MS;
}

