```js
/* ------------------------- upstream governor ------------------------- */
const MAX_INFLIGHT = 4;
const RATE_PER_SEC = 6;
const RATE_BURST = 6;
let tokens = RATE_BURST;
let lastRefill = Date.now();
let inflight = 0;
const queue = [];  // { priority, resolve }

function refill() {
  const now = Date.now();
  const add = ((now - lastRefill) / 1000) * RATE_PER_SEC;
  if (add > 0) { tokens = Math.min(RATE_BURST, tokens + add); lastRefill = now; }
}

function acquire(priority) {
  return new Promise((resolve, reject) => {
    const job = { priority, resolve };
    if (priority === 0) {
      // user waits: jump ahead of background jobs
      const i = queue.findIndex((q) => q.priority > 0);
      if (i === -1) queue.push(job); else queue.splice(i, 0, job);
    } else queue.push(job);
    pump();
  });
}
