+/* Temporary harness: how many upstream calls do N simultaneous users cost? */
+const http = require("http");
+const base = "http://localhost:3001";
+
+function get(path) {
+  return new Promise((resolve) => {
+    const t0 = Date.now();
+    http
+      .get(base + path, (r) => {
+        let n = 0;
+        r.on("data", (c) => (n += c.length));
+        r.on("end", () => resolve({ path, status: r.statusCode, ms: Date.now() - t0, bytes: n }));
+      })
+      .on("error", (e) => resolve({ path, status: 0, err: e.message, ms: Date.now() - t0 }));
+  });
+}
+
+function stats() {
+  return new Promise((resolve) => {
+    http.get(base + "/api/stats", (r) => {
+      let s = "";
+      r.on("data", (c) => (s += c));
+      r.on("end", () => resolve(JSON.parse(s)));
+    });
+  });
+}
+
+const ok = (arr) => arr.filter((r) => r.status === 200).length;
+
+(async () => {
+  const before = await stats();
+
+  const t0 = Date.now();
+  const same = await Promise.all(Array.from({ length: 50 }, () => get("/api/feed?tab=mostviewed")));
+  const sameMs = Date.now() - t0;
+  const mid = await stats();
+
